function example() {
  const [show, setShow] = useState(true);

  return (
    <Tags>
      <Tag color="primary" size="medium">
        Primary Medium
      </Tag>
      <Tag color="success" isRounded>
        Success Rounded
      </Tag>
      {/* Dismissible tag */}
      {show && (
        <Tag color="danger">
          Danger
          <Delete
            size="small"
            ariaLabel="Remove Danger"
            onClick={() => setShow(false)}
          />
        </Tag>
      )}
      <Tag color="info">Info</Tag>
    </Tags>
  );
}
